# Phase 3D validation protocol V2.1 (candidate): corrects ONLY the covariance validation rule of V2 (config/dlm_validation_protocol_v2_1.json). A POST HOC revision after reviewing the V2 run; not prespecified, not an unchanged criterion.
# Reads aggregate files of a V2 run folder only (the saved 3 x 3 cross-basis covariance matrices); never reads participant data, never refits, never changes a production fit, covariance estimator, simulation, seed, draw count or convergence setting.

#' Load the V2.1 candidate protocol (config/dlm_validation_protocol_v2_1.json).
#' @export
siw_dlm_validation_protocol_v21 <- function(path = NULL) {
  if (is.null(path)) { root <- siw_root(); cand <- c(file.path(root, "config", "dlm_validation_protocol_v2_1.json"), file.path(root, "extdata", "dlm_validation_protocol_v2_1.json"), file.path(root, "inst", "extdata", "dlm_validation_protocol_v2_1.json")); path <- cand[file.exists(cand)][1L]; if (is.na(path)) stop("SIW_DLM_PROTOCOL_V21_NOT_FOUND", call. = FALSE) }
  p <- jsonlite::fromJSON(path, simplifyVector = FALSE); p$protocol_path <- normalizePath(path, winslash = "/"); p$protocol_hash <- siw_file_hash(path)$value; p
}

#' Exact worst-case relative standard-error difference between two covariance matrices in identical coordinates.
#' With generalized eigenvalues lambda_j of V_candidate v = lambda V_reference v, delta_SE = max_j |sqrt(lambda_j) - 1| = sup over a != 0 of |sqrt(a' V_candidate a / a' V_reference a) - 1|.
#' Cholesky reduction (base R) and a symmetric eigenvalue calculation on the symmetric parts (a standard error depends only on the symmetric part of a covariance matrix). Non-finite, incompatible or non-positive-definite input FAILS (ok = FALSE, delta_se = NA): no jitter, no eigenvalue clipping, no repair.
#' @return list(ok, reason, delta_se, delta_se_swapped, lambda, asymmetry_candidate, asymmetry_reference, asymmetry_affine_candidate, asymmetry_affine_reference)
#' @export
siw_dlm_delta_se <- function(V_candidate, V_reference) {
  out <- function(ok, reason, ...) utils::modifyList(list(ok = ok, reason = reason, delta_se = NA_real_, delta_se_swapped = NA_real_, lambda = NA_real_, asymmetry_candidate = NA_real_, asymmetry_reference = NA_real_, asymmetry_affine_candidate = NA_real_, asymmetry_affine_reference = NA_real_), list(...))
  bad <- function(V, nm) if (!is.matrix(V) || !is.numeric(V)) paste(nm, "is not a numeric matrix") else if (nrow(V) < 1L || nrow(V) != ncol(V)) paste(nm, "is not a non-empty square matrix") else if (!all(is.finite(V))) paste(nm, "has non-finite entries") else NULL
  e <- bad(V_candidate, "candidate"); if (is.null(e)) e <- bad(V_reference, "reference"); if (!is.null(e)) return(out(FALSE, e)); if (!identical(dim(V_candidate), dim(V_reference))) return(out(FALSE, "dimensions of candidate and reference differ"))
  sym <- function(V) (V + t(V)) / 2; Cs <- sym(V_candidate); Rs <- sym(V_reference)
  rc <- tryCatch(chol(Rs), error = function(e) NULL); if (is.null(rc)) return(out(FALSE, "reference is not positive definite (Cholesky failed)")); cc <- tryCatch(chol(Cs), error = function(e) NULL); if (is.null(cc)) return(out(FALSE, "candidate is not positive definite (Cholesky failed)"))
  reduce <- function(A, ch) { X <- backsolve(ch, A, transpose = TRUE); M <- t(backsolve(ch, t(X), transpose = TRUE)); (M + t(M)) / 2 }                                                           # R'^-1 A R^-1 with A = R'R-reduced matrix
  lam <- eigen(reduce(Cs, rc), symmetric = TRUE, only.values = TRUE)$values; if (any(!is.finite(lam)) || any(lam <= 0)) return(out(FALSE, "non-positive or non-finite generalized eigenvalue"))
  lam2 <- eigen(reduce(Rs, cc), symmetric = TRUE, only.values = TRUE)$values; asym <- function(V) max(abs(V - t(V))) / max(abs(V)); aff <- function(V, ch) norm(reduce((V - t(V)) / 2, ch), "2")
  out(TRUE, "", delta_se = max(abs(sqrt(lam) - 1)), delta_se_swapped = max(abs(sqrt(lam2) - 1)), lambda = lam, asymmetry_candidate = asym(V_candidate), asymmetry_reference = asym(V_reference), asymmetry_affine_candidate = aff(V_candidate, rc), asymmetry_affine_reference = aff(V_reference, rc))
}

.siw_v21_env <- function() {
  ext <- tryCatch(extSoftVersion(), error = function(e) character()); lav <- tryCatch(La_version(), error = function(e) NA_character_); lal <- tryCatch(La_library(), error = function(e) NA_character_)
  fld <- function(value, what) { v <- if (is.null(value) || length(value) == 0L || is.na(value)) "" else as.character(value); list(value = v, available = nzchar(v), note = if (nzchar(v)) "reported by R" else paste0("UNAVAILABLE: this R build reports no ", what, " (empty or missing); the implementation is not inferred")) }
  list(r_version = R.version.string, platform = R.version$platform, os = utils::sessionInfo()$running, la_version = fld(lav, "LAPACK version"), la_library = fld(lal, "LAPACK library path"), blas = fld(if ("BLAS" %in% names(ext)) unname(ext[["BLAS"]]) else "", "BLAS library path"), extSoftVersion = lapply(as.list(ext), function(z) fld(z, "value")), locale_collate = Sys.getlocale("LC_COLLATE"))
}

.siw_v21_read <- function(dir, f) { p <- file.path(dir, f); if (!file.exists(p) || file.info(p)$size < 5) NULL else utils::read.csv(p, stringsAsFactors = FALSE, check.names = FALSE) }

#' Run the V2.1 covariance check on the aggregate files of a V2 run folder (read only). No data are read and nothing is refitted: if required files are missing the run reports exactly which and fails the input-provenance status.
#' @param v2_run_dir a dlmvalidatev2_* folder; out_dir a new folder
#' @export
siw_run_dlm_covariance_v21 <- function(v2_run_dir, out_dir, config = siw_load_config()) {
  t0 <- proc.time()[["elapsed"]]; v2_run_dir <- normalizePath(v2_run_dir, winslash = "/", mustWork = TRUE); dir.create(out_dir, recursive = TRUE, showWarnings = FALSE); out_dir <- normalizePath(out_dir, winslash = "/")
  if (startsWith(out_dir, paste0(v2_run_dir, "/"))) stop("SIW_V21_OUTPUT_INSIDE_V2_RUN", call. = FALSE)
  options(sieccwinter.log_file = file.path(out_dir, "run_v21.log")); on.exit(options(sieccwinter.log_file = NULL), add = TRUE)
  p21 <- siw_dlm_validation_protocol_v21(); p1 <- siw_dlm_validation_protocol(); p2 <- siw_dlm_validation_protocol_v2(); sm0 <- siw_source_manifest(); siw_log("V2.1 covariance check; protocol ", p21$protocol_hash, "; source fingerprint ", sm0$fingerprint); W <- function(x, f) siw_write_csv(x, file.path(out_dir, f))
  env <- .siw_v21_env(); jsonlite::write_json(env, file.path(out_dir, "dlm_v21_environment.json"), auto_unbox = TRUE, pretty = TRUE, null = "null"); writeLines(utils::capture.output(print(utils::sessionInfo())), file.path(out_dir, "dlm_v21_sessionInfo.txt"))
  need <- c("dlm_v2_covariance_matrices.csv", "dlm_v2_metadata.json", "RUN_MANIFEST.csv", "dlm_v2_checks.csv", "dlm_v2_exact_differences_visible.csv", "DLM_V2_STATUS.txt", "simulation_diagnostic/dlm_sd_covariance_agreement.csv", "simulation_diagnostic/dlm_sd_covariance_trace.csv", "v1_component/dlm_verification_checks.csv", "v1_component/dlm_mc_stability.csv")
  missing <- need[!file.exists(file.path(v2_run_dir, need))]; tolr <- c(continuous = p1$criteria$independent_route$fitted_quantities_rel, binomial = p1$criteria$independent_route$binomial_fitted_quantities_rel_accepted_epsilon)
  tol_tab <- data.frame(outcome_type = c("continuous", "binary_at_accepted_epsilon"), value = unname(tolr), source_file = "config/dlm_validation_protocol.json", source_field = c("criteria.independent_route.fitted_quantities_rel", "criteria.independent_route.binomial_fitted_quantities_rel_accepted_epsilon"), v1_protocol_hash = p1$protocol_hash, stringsAsFactors = FALSE); W(tol_tab, "dlm_v21_tolerance_source.csv")
  if (length(missing)) {
    W(data.frame(file = need, present = file.exists(file.path(v2_run_dir, need)), stringsAsFactors = FALSE), "dlm_v21_input_files.csv")
    st <- c(EXECUTION_STATUS = "PASS", INPUT_PROVENANCE_STATUS = "FAIL", COVARIANCE_RULE_V21_STATUS = "NOT_TESTED", SOURCE_INTEGRITY_STATUS = if (isTRUE(siw_source_manifest_diff(sm0, siw_source_manifest())$identical_fingerprint)) "PASS" else "FAIL"); writeLines(c(paste0(names(st), "=", st), paste0("MISSING_FILES=", paste(missing, collapse = ";")), "NOTHING WAS REFITTED: the required aggregate files are absent from the V2 run folder.", "ADOPTION=PENDING_REVIEW"), file.path(out_dir, "DLM_V21_STATUS.txt"))
    writeLines(c("# V2.1 covariance check: required input files are missing", "", paste0("* V2 run folder: `", basename(v2_run_dir), "`"), paste0("* Missing: ", paste(missing, collapse = ", ")), "", "No covariance check was made; no model was refitted."), file.path(out_dir, "RUN_SUMMARY.md"))
    return(list(out_dir = out_dir, statuses = st, missing = missing, status = "VERIFICATION_FAILURE", checks = NULL))
  }
  rd <- function(f) .siw_v21_read(v2_run_dir, f); man <- rd("RUN_MANIFEST.csv"); meta <- jsonlite::fromJSON(file.path(v2_run_dir, "dlm_v2_metadata.json"), simplifyVector = FALSE)
  mh <- vapply(seq_len(nrow(man)), function(i) { f <- file.path(v2_run_dir, man$file[i]); if (!file.exists(f)) NA_character_ else siw_file_hash(f)$value }, ""); man_bad <- is.na(mh) | toupper(mh) != toupper(man$hash)
  used <- need[need != "RUN_MANIFEST.csv"]; used_listed <- used %in% man$file; used_ok <- used %in% man$file[!man_bad]
  prov <- data.frame(item = c("manifest rows verified", "manifest rows with a hash mismatch or missing file", paste0("input file listed in the manifest and verified: ", used)), value = c(nrow(man), sum(man_bad), used_ok), ok = c(TRUE, sum(man_bad) == 0L, used_ok), stringsAsFactors = FALSE)
  cmp <- function(item, recorded, current) data.frame(item = item, value = paste0("recorded ", recorded, "; current ", current), ok = identical(toupper(recorded), toupper(current)), stringsAsFactors = FALSE)
  prov <- rbind(prov, cmp("V2 protocol hash in the run equals the current V2 protocol file", meta$v2_protocol_hash, p2$protocol_hash), cmp("V1 protocol hash in the run equals the current V1 protocol file", meta$v1_protocol_hash, p1$protocol_hash), cmp("configuration hash in the run equals the current configuration", meta$config_hash, config$config_hash))
  cv <- rd("dlm_v2_covariance_matrices.csv"); ag <- rd("simulation_diagnostic/dlm_sd_covariance_agreement.csv"); tr <- rd("simulation_diagnostic/dlm_sd_covariance_trace.csv"); ids <- unique(cv$result_id)
  shape_ok <- length(ids) == 9L && all(table(paste(cv$result_id, cv$route)) == 9L) && all(c("production", "independent") %in% cv$route) && all(is.finite(cv$value)); prov <- rbind(prov, data.frame(item = "nine models, two routes, 3 x 3 finite entries each", value = paste(length(ids), "models;", nrow(cv), "rows"), ok = shape_ok, stringsAsFactors = FALSE))
  rot <- ag$rotation_max_deviation_from_identity[match(ids, ag$result_id)]; rot_ok <- !anyNA(rot) && all(rot <= 1e-12); prov <- rbind(prov, data.frame(item = "identical coordinates (rotation between the two parameterisations equals the identity within 1e-12)", value = paste0("max deviation ", signif(suppressWarnings(max(rot)), 3)), ok = rot_ok, stringsAsFactors = FALSE))
  W(prov, "dlm_v21_provenance.csv"); prov_ok <- all(prov$ok)
  fam <- stats::setNames(tr$family[tr$route == "production"], tr$result_id[tr$route == "production"]); V1c <- rd("v1_component/dlm_verification_checks.csv"); mat <- function(id, r) { z <- cv[cv$result_id == id & cv$route == r, ]; matrix(z$value[order(z$col, z$row)], 3L) }
  rows <- list(); for (id in ids) { Vc <- mat(id, "production"); Vr <- mat(id, "independent"); d <- siw_dlm_delta_se(Vc, Vr); f <- fam[[id]]; tol <- if (identical(f, "binomial")) tolr[["binomial"]] else tolr[["continuous"]]
    dse <- V1c[V1c$result_id == id & V1c$quantity == "lag_standard_errors", "max_rel_diff"]; dcs <- V1c[V1c$result_id == id & V1c$quantity == "cumulative_se_curve", "max_rel_diff"]; proxy <- ag$lag_space_relative_difference[match(id, ag$result_id)] / 2; ok <- isTRUE(d$ok) && is.finite(d$delta_se) && d$delta_se <= tol
    rows[[length(rows) + 1L]] <- data.frame(result_id = id, family = f, tolerance = tol, tolerance_source_field = if (identical(f, "binomial")) "criteria.independent_route.binomial_fitted_quantities_rel_accepted_epsilon" else "criteria.independent_route.fitted_quantities_rel", delta_se = d$delta_se, delta_se_swapped_roles = d$delta_se_swapped, margin_tolerance_over_delta = tol / d$delta_se,
      sqrt_lambda_minus_1_a = if (isTRUE(d$ok)) sqrt(d$lambda[1L]) - 1 else NA_real_, sqrt_lambda_minus_1_b = if (isTRUE(d$ok)) sqrt(d$lambda[2L]) - 1 else NA_real_, sqrt_lambda_minus_1_c = if (isTRUE(d$ok)) sqrt(d$lambda[3L]) - 1 else NA_real_, asymmetry_candidate_max_element_scale = d$asymmetry_candidate, asymmetry_reference_max_element_scale = d$asymmetry_reference, asymmetry_candidate_affine = d$asymmetry_affine_candidate, asymmetry_reference_affine = d$asymmetry_affine_reference,
      asymmetry_exceeds_se_tolerance = isTRUE(max(d$asymmetry_affine_candidate, d$asymmetry_affine_reference) > tol), symmetric_part_used = TRUE, direct_max_rel_lag_se_v1 = dse, direct_max_rel_cumulative_se_v1 = dcs, delta_se_at_least_direct_se_differences = isTRUE(d$delta_se * (1 + 1e-6) + 1e-15 >= max(dse, dcs)), v2_proxy_half_max_element_metric = proxy, v2_proxy_over_delta_se = proxy / d$delta_se,
      invalid_reason = d$reason, status = if (ok) "PASS" else "FAIL", stringsAsFactors = FALSE) }
  K <- do.call(rbind, rows); W(K, "dlm_v21_covariance_checks.csv"); cov_status <- if (!nrow(K)) "NOT_TESTED" else if (all(K$status == "PASS")) "PASS" else "FAIL"
  # carried forward (previously reviewed evidence, not recomputed) and the Monte Carlo rule with actual discrepancies
  v2st <- readLines(file.path(v2_run_dir, "DLM_V2_STATUS.txt")); kv <- do.call(rbind, lapply(strsplit(v2st[grepl("^[A-Z_0-9]+=", v2st)], "=", fixed = TRUE), function(z) data.frame(item = z[1L], value = paste(z[-1L], collapse = "="), stringsAsFactors = FALSE))); kv$label <- "carried forward from the V2 run as previously reviewed evidence (PHASE3D6); not recomputed here"; W(kv, "dlm_v21_carried_forward_v2_statuses.csv")
  dq <- c("lag_standard_errors", "pointwise_lower_95", "pointwise_upper_95", "cumulative_se_curve", "cumulative_lower_95_curve", "cumulative_upper_95_curve"); D <- V1c[V1c$quantity %in% dq, c("result_id", "group", "quantity", "max_abs_diff", "max_rel_diff", "criterion", "status")]; D$label <- "direct SE comparison retained unchanged; carried forward from the V2 run (previously reviewed evidence, not recomputed)"; W(D, "dlm_v21_carried_forward_direct_se_checks.csv")
  mc <- rd("v1_component/dlm_mc_stability.csv"); ex <- rd("dlm_v2_exact_differences_visible.csv"); st1 <- p1$criteria$simultaneous_mc_stability
  mcT <- data.frame(result_id = mc$result_id, deviation_from_100000_draw_value = mc$relative_deviation_package_vs_large, threshold_deviation = st1$max_relative_deviation_of_seeded_from_large, spread_across_20_seeds = mc$spread_across_seeds, threshold_spread = st1$max_spread_across_alternative_seeds_absolute, lags_excluding_zero_all_critical_values = mc$lags_excluding_zero_all_critical_values, status = mc$status, label = "Monte Carlo rule unchanged; carried forward (needs the simulation draws), actual values next to the declared thresholds", stringsAsFactors = FALSE)
  W(mcT, "dlm_v21_monte_carlo_rule_actuals.csv"); x2 <- ex[, c("result_id", "draws", "native_relative_difference", "native_monte_carlo_bound")]; x2$reference_relative_difference <- ifelse(is.na(ex$reference_critical), NA, abs(ex$reference_critical - ex$production_package) / ex$production_package); x2$label <- "cross-implementation and reference relative differences with the declared 5% bound; carried forward"; W(x2, "dlm_v21_cross_implementation_actuals.csv")
  rq <- c("PRODUCTION_REPRODUCTION_STATUS", "DETERMINISTIC_AGREEMENT_STATUS", "ORIENTATION_ALIGNED_SIMULATION_STATUS", "NATIVE_ORIENTATION_MC_STATUS", "REFERENCE_DETERMINISTIC_STATUS", "REFERENCE_SIMULATION_MC_STATUS"); carried <- stats::setNames(kv$value, kv$item); open <- carried[c("MANUSCRIPT_CONCORDANCE_STATUS", "FIGURE_PROVENANCE_STATUS", "DLNM_EQUALITY_STATUS")]; carried_open <- any(open %in% c("REVIEW", "NOT_TESTED")) || any(carried[rq] != "PASS")
  sm1 <- siw_source_manifest(); changed <- !isTRUE(siw_source_manifest_diff(sm0, sm1)$identical_fingerprint); W(sm0$manifest, "source_manifest_v21.csv")
  st <- c(EXECUTION_STATUS = "PASS", INPUT_PROVENANCE_STATUS = if (prov_ok) "PASS" else "FAIL", COVARIANCE_RULE_V21_STATUS = cov_status, SOURCE_INTEGRITY_STATUS = if (changed) "FAIL" else "PASS")
  writeLines(c(paste0(names(st), "="  , st), paste0("COVARIANCE_MODELS_PASS=", sum(K$status == "PASS"), "_OF_", nrow(K)), paste0("LARGEST_DELTA_SE=", signif(max(K$delta_se, na.rm = TRUE), 4)), paste0("CARRIED_FORWARD_", names(carried[c(rq, "MANUSCRIPT_CONCORDANCE_STATUS", "FIGURE_PROVENANCE_STATUS", "DLNM_EQUALITY_STATUS")]), "=", carried[c(rq, "MANUSCRIPT_CONCORDANCE_STATUS", "FIGURE_PROVENANCE_STATUS", "DLNM_EQUALITY_STATUS")], " (previously reviewed evidence, not recomputed)"),
    "RULE_NOTE=V2.1 replaces an invalid covariance proxy after reviewing V2; it is a post hoc correction, not a prespecified or unchanged criterion", "ADOPTION=PENDING_REVIEW"), file.path(out_dir, "DLM_V21_STATUS.txt")); writeLines(c(paste0("SOURCE_FINGERPRINT_SHA256=", sm0$fingerprint), paste0("FILES=", sm0$n_files), paste0("SOURCE_CHANGED_DURING_RUN=", toupper(as.character(changed)))), file.path(out_dir, "SOURCE_FINGERPRINT.txt"))
  jsonlite::write_json(list(package_version = siw_pkg_version(), batch = "3D7_covariance_rule_V21_candidate", v21_protocol_hash = p21$protocol_hash, v2_protocol_hash = p2$protocol_hash, v1_protocol_hash = p1$protocol_hash, v2_run = basename(v2_run_dir), v2_run_input_hash = meta$input_hash, v2_run_fingerprint = meta$source_fingerprint_sha256, source_fingerprint_sha256 = sm0$fingerprint, source_files = sm0$n_files, statuses = as.list(st), adoption = "PENDING_REVIEW", created_utc = format(Sys.time(), tz = "UTC", usetz = TRUE), seconds = round(proc.time()[["elapsed"]] - t0, 2)), file.path(out_dir, "dlm_v21_metadata.json"), auto_unbox = TRUE, pretty = TRUE, null = "null", digits = NA)
  writeLines(c("# V2.1 covariance rule check (candidate; adoption pending review)", "", paste0("* Protocol `", p21$protocol_hash, "`; V2 run `", basename(v2_run_dir), "`; source fingerprint `", sm0$fingerprint, "` (", sm0$n_files, " files)"), "", "## New statuses", "", paste0("* ", names(st), ": ", st), "",
    "## Covariance rule", "", "* delta_SE = max |sqrt(lambda_j) - 1| over the generalized eigenvalues of V_candidate v = lambda V_reference v (3 x 3 cross-basis covariances, identical coordinates): the exact worst-case relative standard-error difference over all nonzero linear contrasts.", paste0("* Tolerances (existing V1 relative SE tolerances): continuous ", tolr[["continuous"]], " (criteria.independent_route.fitted_quantities_rel); binary at the accepted epsilon ", tolr[["binomial"]], " (criteria.independent_route.binomial_fitted_quantities_rel_accepted_epsilon)."),
    paste0("* Largest delta_SE ", signif(max(K$delta_se, na.rm = TRUE), 4), "; models passing ", sum(K$status == "PASS"), " of ", nrow(K), "."), "* This replaces an invalid proxy and changes the covariance metric AFTER reviewing V2: a post hoc correction, not a prespecified or unchanged criterion.", "* The symmetric part is used (the SE of any contrast depends only on it); asymmetry is recorded.", "", "## Carried forward (previously reviewed evidence, not recomputed)", "", paste0("* ", names(carried[c(rq, "MANUSCRIPT_CONCORDANCE_STATUS", "FIGURE_PROVENANCE_STATUS", "DLNM_EQUALITY_STATUS")]), ": ", carried[c(rq, "MANUSCRIPT_CONCORDANCE_STATUS", "FIGURE_PROVENANCE_STATUS", "DLNM_EQUALITY_STATUS")]), "", "Nothing in this folder contains participant-level values."), file.path(out_dir, "RUN_SUMMARY.md"))
  list(out_dir = out_dir, statuses = st, checks = K, provenance = prov, carried = carried, mc = mcT, environment = env, status = if (any(st == "FAIL")) "VERIFICATION_FAILURE" else if (carried_open) "OK_WITH_CARRIED_FORWARD_OPEN_ITEMS" else "OK", seconds = proc.time()[["elapsed"]] - t0)
}
